pub type DispatchResult {
  Reply(json: String)
  NoReply
  ProtocolError(json: String)
}

pub fn handle_line(pool: Pool, line: String) -> DispatchResult {
  case json.parse(line, message_decoder()) {
    Ok(message) -> dispatch(pool, message)
    Error(_) -> ProtocolError(error_response(None, -32_700, "Parse error"))
  }
}

fn dispatch(pool: Pool, body_text: String) -> Response(mist.ResponseData) {
  case server.handle_line(pool, body_text) {
    server.Reply(json) -> json_response(200, json)
    server.ProtocolError(json) -> json_response(200, json)
    server.NoReply -> empty_response(204)
  }
}

fn dispatch_line(state: State, body: String) -> Nil {
  let mcp_id = peek_mcp_id(body)
  let _pid = process.spawn_unlinked(fn() {
    request_workers.insert(mcp_id, process.self())
    case server.handle_line(state.pool, body) {
      server.Reply(json) -> request_workers.send_reply(state.writer, WriteResponse(json))
      server.ProtocolError(json) -> request_workers.send_reply(state.writer, WriteResponse(json))
      server.NoReply -> request_workers.send_reply(state.writer, WorkerDone)
    }
    request_workers.delete(mcp_id)
  })
  Nil
}

