fn allowed_tool_definitions() -> List(Json) {
  let curated = [
    #("echo", echo_tool_definition),
    #("hover", hover_tool_definition),
    #("find_references", find_references_tool_definition),
    // ...one #(name, builder) pair per tool...
  ]
