fn decode_find_references_arguments(args: Option(Dynamic)) -> Result(#(String, Int, Int, Bool, Int), String) {
  use raw <- result.try(option.to_result(args, "arguments object missing"))
  let decoder = {
    use uri <- decode.field("uri", decode.string)
    use line <- decode.field("line", decode.int)
    use character <- decode.field("character", decode.int)
    use include_decl <- decode.optional_field("include_declaration", True, decode.bool)
    use timeout_arg <- decode.optional_field("timeout_ms", None, decode.map(decode.int, Some))
    decode.success(#(uri, line, character, include_decl, timeout_arg))
  }
  case decode.run(raw, decoder) {
    Ok(#(uri, line, char, incl, timeout_arg)) -> Ok(#(uri, line, char, incl, finalize_timeout("find_references", find_references.default_timeout_ms, uri, timeout_arg)))
    Error(_) -> Error("expected `uri: string`, `line: int`, `character: int`, optional `include_declaration: bool`, optional `timeout_ms: int`")
  }
}

fn decode_tool_call(params: Option(Dynamic)) -> Result(#(String, Option(Dynamic)), String) {
  use raw <- result.try(option.to_result(params, "missing params"))
  let decoder = {
    use name <- decode.field("name", decode.string)
    use args <- decode.optional_field("arguments", None, decode.optional(decode.dynamic))
    decode.success(#(name, args))
  }
  decode.run(raw, decoder)
  |> result.map_error(fn(_) { "params shape did not match tools/call schema" })
}

