fn handle_hover(pool: Pool, id: Id, arguments: Option(Dynamic)) -> String {
  case decode_position_with_timeout(arguments, "hover", hover.default_timeout_ms) {
    Error(reason) -> error_response(Some(id), -32_602, "Invalid hover params: " <> reason)
    Ok(#(uri, line, character, timeout_ms)) ->
      case hover.handle(pool, uri, line, character, timeout_ms) {
        Ok(json_text) -> success_response(id, fn() { tool_text_result(json_text, False) })
        Error(hover.SessionFailed(reason)) -> success_response(id, fn() { tool_text_result(reason, True) })
        Error(hover.RequestFailed(reason)) -> success_response(id, fn() { tool_text_result(reason, True) })
      }
  }
}

