pub fn main() -> Nil {
  redirect_erl_crash_dump()
  case handle_meta_flags(argv()) {
    Handled -> Nil
    Continue ->
      case boot() {
        Error(reason) -> { log.error("..." <> reason); Nil }
        Ok(_pid) -> {
          let cfg = config.cached()
          log.info("pharos starting (transport=" <> transport_label(cfg.transport) <> ")")
          post_boot_dispatch()
          process.sleep_forever()
        }
      }
  }
}

